const body = $json.body ?? $json;
const slug = (body.project_slug ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!slug) throw new Error('project_slug is required in the JSON body.');
const regenRaw = (body.regen_ids ?? '').toString();
const regenIds = regenRaw.split(/[，,\s]+/).map((x) => x.trim().toLowerCase()).filter((x) => /^shot_[a-z0-9_]+$/.test(x));
const model = (body.video_model ?? '').toString().trim() || 'google/veo-3.1-lite';
const resolution = ['480p', '720p'].includes((body.video_resolution ?? '').toString()) ? body.video_resolution.toString() : '720p';
const shotIdsRaw = (body.shot_ids ?? '').toString();
const shotIds = shotIdsRaw.split(/[,\s]+/).map((x) => x.trim().toLowerCase()).filter((x) => /^shot_[a-z0-9_]+$/.test(x));
return [{ json: { slug, regen_ids: regenIds, shot_ids: shotIds, model, resolution, aspect_ratio: '16:9' } }];

const metas = $('Build Video Payload').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json ?? {};
  const meta = metas[i] ? metas[i].json : {};
  const slug = meta.slug ?? $('Build Request').first().json.slug;
  const jobId = (resp.id ?? '').toString();
  if (!jobId) {
    const msg = resp.error?.message ?? resp.error ?? 'video job submit failed';
    out.push({ json: { slug, model: meta.model ?? 'google/veo-3.1-lite', shotId: meta.shotId ?? ('unknown_' + i), jobId: '', pollUrl: '', round: 0, state: 'failed', error: String(msg).slice(0, 300) } });
    continue;
  }
  out.push({ json: { slug, model: meta.model ?? 'google/veo-3.1-lite', shotId: meta.shotId, jobId, pollUrl: 'https://openrouter.ai/api/v1/videos/' + jobId, round: 0, state: 'pending', error: '' } });
}
return out;

// Settle each poll result against the per-job state carried through the loop.
// Pairing is by jobId (unique per job) — never by item index — so it stays
// correct when the pending subset shrinks between rounds.
const MAX_ROUNDS = 120;

// Prior state per job: Round Start on the first settle, then the previous
// round's Any Pending? output. runIndex is passed explicitly because
// $().all() defaults to run 0 (the first round), not the latest.
const prevByJobId = {};
for (const it of $('Round Start').all()) {
  if (it.json.jobId) prevByJobId[it.json.jobId] = it.json;
}
if ($runIndex > 0) {
  for (const it of $('Any Pending?').all(0, $runIndex - 1)) {
    if (it.json.jobId) prevByJobId[it.json.jobId] = it.json;
  }
}

const slugFallback = $('Build Request').first().json.slug;
const inputs = $input.all();
const out = [];
for (let i = 0; i < inputs.length; i++) {
  const resp = inputs[i].json ?? {};
  const jobId = (resp.id ?? '').toString();
  const prev = prevByJobId[jobId];
  if (!prev) {
    // Poll result with no matching prior state — treat as failed rather than
    // silently dropping the shot.
    out.push({
      json: {
        slug: slugFallback,
        model: '',
        shotId: 'unknown_' + (jobId || ('index_' + i)),
        jobId,
        pollUrl: '',
        round: 0,
        state: 'failed',
        error: String(resp.error?.message ?? resp.error ?? 'no prior state for poll result').slice(0, 300),
      },
    });
    continue;
  }
  if (prev.state === 'done' || prev.state === 'failed') {
    out.push({ json: prev }); // already terminal — do not re-settle
    continue;
  }
  const status = typeof resp.status === 'string' ? resp.status.toLowerCase() : '';
  let state = 'pending';
  let error = prev.error ?? '';
  if (status === 'completed') {
    state = 'done';
  } else if (['failed', 'cancelled', 'expired'].includes(status)) {
    state = 'failed';
    error = String(resp.error ?? ('generation ' + (status || 'failed'))).slice(0, 300);
  } else if (prev.round + 1 >= MAX_ROUNDS) {
    state = 'failed';
    error = 'timed out waiting for video generation';
  }
  out.push({
    json: {
      slug: prev.slug,
      model: prev.model,
      shotId: prev.shotId,
      jobId: prev.jobId,
      pollUrl: prev.pollUrl,
      round: prev.round + 1,
      state,
      error,
    },
  });
}
return out;

// Per-item: emit a content URL for every settled "done" item flowing through
// Has Done?'s true branch (the IF node passes items through unchanged).
const slug = $('Build Request').first().json.slug;
const out = [];
for (const item of $input.all()) {
  const settled = item.json;
  out.push({
    json: {
      slug,
      shotId: settled.shotId,
      model: settled.model,
      contentUrl: 'https://openrouter.ai/api/v1/videos/' + settled.jobId + '/content?index=0',
    },
  });
}
return out;
